<?php
/** Authenticated client workspace presentation. */
defined('ABSPATH') || exit;

function dxcp_portal_url($section = 'overview', $project = 0, $extra = []) {
    return add_query_arg(array_merge(['section' => $section, 'project_id' => absint($project)], $extra), home_url('/dashboard/'));
}
function dxcp_icon($name) {
    $paths = [
        'overview'=>'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
        'journey'=>'<path d="M5 5h14v14H5zM9 9h6M9 13h6M9 17h3"/><path d="M9 3v4M15 3v4"/>',
        'tasks'=>'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 9 2 2 4-4M8 16h8"/>',
        'drive'=>'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9H3z"/>',
        'payments'=>'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h3"/>',
        'sessions'=>'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M8 15h2M14 15h2"/>',
        'support'=>'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 12H2v6h4v-6zm16 0h2v6h-4v-6zM18 20l-6 1"/>',
        'profile'=>'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',
        'arrow'=>'<path d="M5 12h14m-5-5 5 5-5 5"/>',
        'external'=>'<path d="M14 3h7v7M21 3 10 14M10 3H3v18h18v-7"/>',
        'check'=>'<path d="m5 12 4 4L19 6"/>',
        'logout'=>'<path d="M9 3H3v18h6M9 12h12m-4-4 4 4-4 4"/>',
        'plus'=>'<path d="M12 5v14M5 12h14"/>',
        'menu'=>'<path d="M3 6h18M3 12h18M3 18h18"/>',
    ];
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name] ?? $paths['drive']).'</svg>';
}
function dxcp_badge($label, $tone = '') { echo '<span class="dxcp-badge '.esc_attr($tone ? 'dxcp-badge--'.$tone : '').'">'.esc_html($label).'</span>'; }
function dxcp_empty($title, $body, $icon = 'drive') { ?>
    <div class="dxcp-empty"><span class="dxcp-empty__icon"><?php echo dxcp_icon($icon); ?></span><h3><?php echo esc_html($title); ?></h3><p><?php echo esc_html($body); ?></p></div>
<?php }
function dxcp_card_heading($eyebrow, $title, $link = '', $label = 'View all') { ?>
    <div class="dxcp-card__heading"><div><p class="dxcp-eyebrow"><?php echo esc_html($eyebrow); ?></p><h2><?php echo esc_html($title); ?></h2></div><?php if ($link) : ?><a class="dxcp-text-link" href="<?php echo esc_url($link); ?>"><?php echo esc_html($label); ?> <?php echo dxcp_icon('arrow'); ?></a><?php endif; ?></div>
<?php }
function dxcp_field($label, $name, $value = '', $type = 'text', $required = false) { ?>
    <label class="dxcp-field"><span><?php echo esc_html($label); ?></span><input type="<?php echo esc_attr($type); ?>" name="<?php echo esc_attr($name); ?>" value="<?php echo esc_attr($value); ?>" <?php echo $required ? 'required' : ''; ?> <?php echo $type === 'url' ? 'placeholder="https://"' : ''; ?>></label>
<?php }
function dxcp_form_start($action, $project = 0, $nonce = '', $multipart = false) { ?>
    <form class="dxcp-form" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" method="post" <?php echo $multipart ? 'enctype="multipart/form-data"' : ''; ?>>
    <input type="hidden" name="action" value="<?php echo esc_attr($action); ?>"><input type="hidden" name="project_id" value="<?php echo absint($project); ?>">
    <?php echo '<input type="hidden" name="'.esc_attr($action === 'dxcp_profile' || $action === 'dxcp_onboarding' ? 'dxcp_nonce' : '_wpnonce').'" value="'.esc_attr(wp_create_nonce($nonce ?: $action)).'">'; ?>
<?php }
function dxcp_phases() {
    return [
        'quotation'=>['Quotation & brief', 'Review your estimate, agree the scope and accept the final quotation.', ''],
        'design'=>['Design', 'Follow the visual direction, layouts and design feedback.', '_dxcp_design_url'],
        'development'=>['Development', 'Explore your staging site as your project takes shape.', '_dxcp_staging_url'],
        'testing'=>['Testing & audit', 'Work through feedback and checks together before launch.', '_dxcp_testing_url'],
        'launch'=>['Launch ready', 'Your live website and the final handover.', '_dxcp_live_url'],
        'post_launch'=>['Post-launch care', 'Keep your website supported as your needs grow.', ''],
    ];
}
function dxcp_render_overview($c) {
    extract($c);
    $pending = array_values(array_filter($tasks, fn($t) => get_post_meta($t->ID, '_dxcp_task_status', true) !== 'done'));
    $open_tickets = array_filter($tickets, fn($t) => !in_array(get_post_meta($t->ID, 'ticket_status', true), ['resolved','cancelled'], true));
    $phase = $project ? get_post_meta($pid, '_dxcp_phase', true) : '';
    $phase_label = dxcp_phases()[$phase][0] ?? 'Getting started';
    ?>
    <div class="dxcp-welcome"><div><p class="dxcp-eyebrow">YOUR SPACE. OUR NEXT CHAPTER.</p><h1>Hello, <?php echo esc_html($first_name); ?><span>✦</span></h1><p><?php echo $project ? 'Everything for '.esc_html($project->post_title).', together in one place.' : 'A clear view of your projects, conversations and next steps.'; ?></p></div><span class="dxcp-date"><?php echo esc_html(wp_date('l, j F')); ?></span></div>
    <div class="dxcp-stats">
        <a href="<?php echo esc_url(dxcp_portal_url('tasks',$pid)); ?>" class="dxcp-stat"><span class="dxcp-stat__icon dxcp-stat__icon--gold"><?php echo dxcp_icon('tasks'); ?></span><span>Waiting on you<strong><?php echo count($pending); ?></strong><small>Client to-dos</small></span><?php echo dxcp_icon('arrow'); ?></a>
        <a href="<?php echo esc_url(dxcp_portal_url('drive',$pid)); ?>" class="dxcp-stat"><span class="dxcp-stat__icon dxcp-stat__icon--blue"><?php echo dxcp_icon('drive'); ?></span><span>Your documents<strong><?php echo count($documents); ?></strong><small>In your private Drive</small></span><?php echo dxcp_icon('arrow'); ?></a>
        <a href="<?php echo esc_url(dxcp_portal_url('payments',$pid)); ?>" class="dxcp-stat"><span class="dxcp-stat__icon dxcp-stat__icon--green"><?php echo dxcp_icon('payments'); ?></span><span>Project balance<strong class="dxcp-stat__money"><?php echo $billing['balance_cents'] === null ? 'To be agreed' : esc_html(dxcp_money($billing['balance_cents'])); ?></strong><small><?php echo $billing['next_due'] ? 'Next due '.esc_html(wp_date('j M',strtotime($billing['next_due']['due_date']))) : 'No payment date scheduled'; ?></small></span><?php echo dxcp_icon('arrow'); ?></a>
    </div>
    <article class="dxcp-project-card"><div class="dxcp-project-card__copy"><p class="dxcp-eyebrow"><?php echo esc_html($service_label); ?> WORKSPACE</p><h2><?php echo esc_html($project ? $project->post_title : 'Good things start with a conversation.'); ?></h2><p><?php echo $project ? esc_html(wp_trim_words(wp_strip_all_tags($project->post_content),25) ?: 'Your next steps, shared files and project updates will appear here.') : 'Your project workspace will appear here once your brief is connected. You can still get in touch through Support.'; ?></p><a class="dxcp-btn dxcp-btn--dark" href="<?php echo esc_url(dxcp_portal_url($service === 'fitness' ? 'sessions' : 'journey',$pid)); ?>"><?php echo $service === 'fitness' ? 'Your coaching sessions' : 'Explore your journey'; ?> <?php echo dxcp_icon('arrow'); ?></a></div><div class="dxcp-project-card__art" aria-hidden="true"><div class="dxcp-orbit dxcp-orbit--one"></div><div class="dxcp-orbit dxcp-orbit--two"></div><span>dx.</span><p><?php echo esc_html($phase_label); ?></p></div></article>
    <div class="dxcp-overview-grid"><article class="dxcp-card"><?php dxcp_card_heading('A LITTLE MOMENTUM','Your next steps',dxcp_portal_url('tasks',$pid)); ?><?php if (!$pending) dxcp_empty('All clear for now','When there’s something for you to do, it will appear here.','check'); else foreach(array_slice($pending,0,4) as $task) dxcp_task_row($task,$pid); ?></article>
    <article class="dxcp-card"><?php dxcp_card_heading('LET’S KEEP THINGS MOVING','Your conversations',dxcp_portal_url('support',$pid)); ?><?php if (!$tickets) dxcp_empty('A direct line','Questions, requests and project feedback all have a home in Support.','support'); else foreach(array_slice($tickets,0,3) as $ticket) : ?><a class="dxcp-list-row" href="<?php echo esc_url(dxcp_portal_url('support',$pid,['ticket_id'=>$ticket->ID])); ?>"><span><strong><?php echo esc_html($ticket->post_title); ?></strong><small>Updated <?php echo esc_html(get_the_modified_date('j M Y',$ticket)); ?></small></span><?php dxcp_badge(dxcp_ticket_status_label(get_post_meta($ticket->ID,'ticket_status',true))); ?></a><?php endforeach; ?><a class="dxcp-text-link dxcp-card__bottom" href="<?php echo esc_url(dxcp_portal_url('support',$pid,['new_ticket'=>1])); ?>"><?php echo dxcp_icon('plus'); ?> Start a conversation</a></article></div>
    <?php if ($quotes) : ?><article class="dxcp-card dxcp-quote-teaser"><?php dxcp_card_heading('FROM IDEA TO AGREEMENT','Your latest quotation',dxcp_portal_url('payments',$pid),'Review quotation'); $q=$quotes[0]; ?><div><strong><?php echo esc_html($q['ref']); ?></strong><?php dxcp_badge(str_replace('_',' ',$q['status'])); ?><span><?php echo esc_html(dxcp_money($q['total_cents'])); ?></span></div><p><?php echo $q['kind']==='final' ? 'Review the agreed scope and terms before accepting your final quotation.' : 'Your calculator estimate is a starting point. Your final scope and payment dates are agreed together.'; ?></p></article><?php endif;
}
function dxcp_task_row($task,$pid) { $status=get_post_meta($task->ID,'_dxcp_task_status',true)?:'todo'; $due=get_post_meta($task->ID,'_dxcp_due_date',true); ?>
    <a class="dxcp-list-row" href="<?php echo esc_url(dxcp_portal_url('tasks',$pid,['task_id'=>$task->ID])); ?>"><span class="dxcp-task-check <?php echo $status==='done'?'is-done':''; ?>"><?php echo dxcp_icon('check'); ?></span><span><strong><?php echo esc_html($task->post_title); ?></strong><small><?php echo $due?'Due '.esc_html(wp_date('j M Y',strtotime($due))):'No deadline set'; ?></small></span><?php dxcp_badge(dxcp_task_display_status($task->ID),$status==='done'?'green':''); ?></a>
<?php }
function dxcp_render_journey($c) { extract($c); ?>
    <div class="dxcp-view-heading"><p class="dxcp-eyebrow">A CLEAR DIRECTION</p><h1>Your project journey</h1><p>One shared view of where we are and what comes next.</p></div>
    <?php if (!$project) { dxcp_empty('Your journey starts here','Once your project is assigned, your agreed milestones and project links will appear here.','journey'); return; }
    if ($service === 'fitness') : ?><article class="dxcp-card"><?php dxcp_card_heading('YOUR COACHING','Small steps. Lasting progress.'); ?><p>Your coaching workspace brings your upcoming sessions, preparation tasks and shared resources together.</p><a class="dxcp-btn" href="<?php echo esc_url(dxcp_portal_url('sessions',$pid)); ?>">View your sessions <?php echo dxcp_icon('arrow'); ?></a></article><?php return; endif;
    $phase=get_post_meta($pid,'_dxcp_phase',true)?:'quotation'; $keys=array_keys(dxcp_phases()); $position=array_search($phase,$keys,true);
    ?><div class="dxcp-journey"><?php foreach(dxcp_phases() as $key=>$stage) : $index=array_search($key,$keys,true); $active=$key===$phase; $complete=$position!==false&&$index<$position; $url=$stage[2]?get_post_meta($pid,$stage[2],true):''; ?>
        <article class="dxcp-milestone <?php echo $active?'is-current':($complete?'is-complete':''); ?>"><span class="dxcp-milestone__number"><?php echo $complete?dxcp_icon('check'):sprintf('%02d',$index+1); ?></span><div><div class="dxcp-inline"><h2><?php echo esc_html($stage[0]); ?></h2><?php dxcp_badge($active?'Current stage':($complete?'Complete':'Coming up'),$active?'gold':($complete?'green':'')); ?></div><p><?php echo esc_html($stage[1]); ?></p><?php if ($url) : ?><a class="dxcp-btn dxcp-btn--small" href="<?php echo esc_url($url); ?>" target="_blank" rel="noopener noreferrer">Open <?php echo esc_html(['design'=>'design file','development'=>'staging site','testing'=>'feedback board','launch'=>'live website'][$key]??'project link'); ?> <?php echo dxcp_icon('external'); ?></a><?php elseif ($key==='quotation') : ?><a class="dxcp-text-link" href="<?php echo esc_url(dxcp_portal_url('payments',$pid)); ?>">Review quotations <?php echo dxcp_icon('arrow'); ?></a><?php elseif ($key==='post_launch') : ?><a class="dxcp-text-link" href="<?php echo esc_url(home_url('/service/retainer/')); ?>">Explore ongoing support <?php echo dxcp_icon('arrow'); ?></a><?php else : ?><span class="dxcp-muted">Your project link will be shared here when it’s ready.</span><?php endif; ?></div></article>
    <?php endforeach; ?></div><aside class="dxcp-callout">These stages reflect updates from D’André. Quotation acceptance is recorded separately when you approve the final quotation.</aside>
<?php }
function dxcp_render_conversation($record,$pid,$is_task=false) {
    $rid=$record->ID; $pid=absint(get_post_meta($rid,'_dxcp_project_id',true)); $status=get_post_meta($rid,$is_task?'_dxcp_task_status':'ticket_status',true)?:($is_task?'todo':'new');
    ?><article class="dxcp-card dxcp-thread"><div class="dxcp-card__heading"><div><p class="dxcp-eyebrow"><?php echo $is_task?'CLIENT TO-DO':'CONVERSATION #'.absint($rid); ?></p><h2><?php echo esc_html($record->post_title); ?></h2></div><?php dxcp_badge($is_task?dxcp_task_display_status($rid):dxcp_ticket_status_label($status)); ?></div><div class="dxcp-thread__intro"><?php echo wpautop(esc_html(wp_strip_all_tags($record->post_content))); ?></div>
    <?php foreach(dxcp_record_attachments($rid) as $file) : dxcp_render_attachment_preview($file); ?><a class="dxcp-file-link" href="<?php echo esc_url($file['url']); ?>"><?php echo dxcp_icon('drive'); echo esc_html($file['title']); ?></a><?php endforeach;
    if (!$is_task) : $eta=get_post_meta($rid,'estimated_completion',true); if ($eta) : ?><p class="dxcp-muted">Estimated completion: <?php echo esc_html($eta); ?></p><?php endif; endif;
    ?><div class="dxcp-thread__messages"><?php $comments=dxcp_comments($rid); if (!$comments) : ?><p class="dxcp-muted">No replies yet. Add a message below to keep everything together.</p><?php endif; foreach($comments as $comment) : ?><div class="dxcp-message <?php echo $comment['own']?'is-own':''; ?>"><div class="dxcp-message__meta"><strong><?php echo esc_html($comment['author']); ?></strong><?php if ($comment['is_staff']) dxcp_badge('D’André’s team'); ?><time><?php echo esc_html(wp_date('j M Y · H:i',strtotime($comment['date'].' '.wp_timezone_string()))); ?></time></div><div><?php echo wpautop(esc_html(wp_strip_all_tags($comment['content']))); ?></div><?php foreach($comment['attachments'] as $file) : dxcp_render_attachment_preview($file); ?><a class="dxcp-file-link" href="<?php echo esc_url($file['url']); ?>"><?php echo dxcp_icon('drive'); echo esc_html($file['title']); ?></a><?php endforeach; ?></div><?php endforeach; ?></div>
    <?php dxcp_form_start('dxcp_comment',$pid,'dxcp_comment_'.$rid,true); ?><input type="hidden" name="record_id" value="<?php echo absint($rid); ?>"><label class="dxcp-field"><span>Add a comment</span><textarea name="message" rows="4" required maxlength="12000" placeholder="Share an update or ask a question…"></textarea></label><label class="dxcp-field dxcp-field--file"><span>Attach an image, document, audio or video (optional · 20 MB max)</span><input type="file" name="dxcp_file" accept=".jpg,.jpeg,.png,.webp,.gif,.pdf,.txt,.docx,.xlsx,.pptx,.mp4,.mov,.mp3,.m4a,.ogg,.wav,.webm"></label><div class="dxcp-form__footer"><small>Files are shared privately with your project team.</small><button class="dxcp-btn dxcp-btn--dark" type="submit">Send comment <?php echo dxcp_icon('arrow'); ?></button></div></form>
    <?php dxcp_form_start($is_task?'dxcp_task_status':'dxcp_ticket_status',$pid,($is_task?'dxcp_task_status_':'dxcp_ticket_status_').$rid); ?><input type="hidden" name="record_id" value="<?php echo absint($rid); ?>"><div class="dxcp-form__footer dxcp-thread__status"><?php if ($is_task) : ?><label class="dxcp-field"><span>Update your progress</span><select name="status"><option value="todo" <?php selected($status,'todo'); ?>>To do</option><option value="in_progress" <?php selected($status,'in_progress'); ?>>In progress</option><option value="waiting" <?php selected($status,'waiting'); ?>>Waiting / need help</option><option value="done" <?php selected($status,'done'); ?>>Ready for review</option></select></label><button class="dxcp-btn dxcp-btn--small" type="submit">Update progress</button><small>Ready for review lets D’André check the task before marking it complete.</small><?php else : ?><input type="hidden" name="status" value="<?php echo in_array($status,['resolved','cancelled'],true)?'open':'resolved'; ?>"><p class="dxcp-muted"><?php echo in_array($status,['resolved','cancelled'],true)?'Need to pick this up again?':'Everything sorted? You can close this conversation.'; ?></p><button class="dxcp-btn dxcp-btn--small" type="submit"><?php echo in_array($status,['resolved','cancelled'],true)?'Reopen conversation':'Mark resolved'; ?></button><?php endif; ?></div></form></article>
<?php }
function dxcp_render_tasks($c) { extract($c); ?><div class="dxcp-view-heading"><p class="dxcp-eyebrow">A LITTLE COLLABORATION</p><h1>Your to-dos</h1><p>The details we need from you to keep your project moving.</p></div><?php if (!$tasks) { dxcp_empty('Nothing waiting on you','Your project tasks and requests will appear here, with room for feedback and files.','tasks'); return; } $selected=absint($_GET['task_id']??($_GET['record_id']??0)); $task=null; foreach($tasks as $item) if ($item->ID===$selected) $task=$item; ?><div class="dxcp-detail-layout"><article class="dxcp-card dxcp-record-list"><?php foreach($tasks as $item) dxcp_task_row($item,$pid); ?></article><?php if($task) : dxcp_render_conversation($task,$pid,true); else : ?><article class="dxcp-card"><?php dxcp_empty('Choose a to-do','Open a task to read the brief, share files and update your progress.','tasks'); ?></article><?php endif; ?></div><?php }
function dxcp_render_support($c) { extract($c); ?><div class="dxcp-view-heading"><p class="dxcp-eyebrow">YOUR DIRECT LINE</p><h1>Let’s work it through.</h1><p>Keep questions, feedback and support requests in one conversation.</p></div><div class="dxcp-detail-layout"><div><article class="dxcp-card dxcp-record-list"><a class="dxcp-btn dxcp-btn--dark" href="<?php echo esc_url(dxcp_portal_url('support',$pid,['new_ticket'=>1])); ?>"><?php echo dxcp_icon('plus'); ?> New conversation</a><label class="dxcp-field dxcp-ticket-search"><span>Find a conversation</span><input type="search" data-dxcp-ticket-search placeholder="Search conversations…"></label><div class="dxcp-ticket-filters" role="group" aria-label="Filter conversations"><button type="button" data-dxcp-ticket-filter="all" aria-pressed="true">All</button><button type="button" data-dxcp-ticket-filter="open" aria-pressed="false">Open</button><button type="button" data-dxcp-ticket-filter="closed" aria-pressed="false">Closed</button></div><p class="dxcp-muted" data-dxcp-ticket-empty hidden>No matching conversations.</p><?php if (!$tickets) dxcp_empty('No conversations yet','Start a conversation and we’ll take it from there.','support'); foreach($tickets as $item) : ?><a data-dxcp-ticket-status="<?php echo esc_attr(get_post_meta($item->ID,'ticket_status',true)?:'new'); ?>" data-dxcp-ticket-title="<?php echo esc_attr($item->post_title); ?>" class="dxcp-list-row" href="<?php echo esc_url(dxcp_portal_url('support',$pid,['ticket_id'=>$item->ID])); ?>"><span><strong><?php echo esc_html($item->post_title); ?></strong><small><?php echo esc_html(get_the_date('j M Y',$item)); ?></small></span><?php dxcp_badge(dxcp_ticket_status_label(get_post_meta($item->ID,'ticket_status',true))); ?></a><?php endforeach; ?></article></div><?php $selected=absint($_GET['ticket_id']??($_GET['record_id']??0)); $ticket=null; foreach($tickets as $item) if($item->ID===$selected) $ticket=$item; if ($ticket && empty($_GET['new_ticket'])) : dxcp_render_conversation($ticket,$pid); else : ?><article class="dxcp-card"><?php dxcp_card_heading('START SOMETHING','New conversation'); dxcp_form_start('dxcp_new_ticket',$pid,'dxcp_new_ticket',true); dxcp_field('Subject','title','','text',true); ?><label class="dxcp-field"><span>How can I help?</span><textarea name="message" rows="6" required maxlength="12000"></textarea></label><label class="dxcp-field"><span>Priority</span><select name="priority"><option value="normal">Normal — a question or request</option><option value="urgent">Urgent — something is blocking my work</option></select></label><label class="dxcp-field"><span>Attach a file (optional)</span><input type="file" name="dxcp_file" accept=".jpg,.jpeg,.png,.webp,.gif,.pdf,.txt,.docx,.xlsx,.pptx,.mp4,.mov,.mp3,.m4a,.ogg,.wav,.webm"></label><button class="dxcp-btn dxcp-btn--dark" type="submit">Start conversation <?php echo dxcp_icon('arrow'); ?></button><p class="dxcp-muted">For passwords or other credentials, ask D’André for a secure sharing method.</p></form></article><?php endif; ?></div><?php }
function dxcp_render_drive($c) { extract($c); ?><div class="dxcp-view-heading"><p class="dxcp-eyebrow">A HOME FOR THE DETAILS</p><h1>Your Drive</h1><p>Your project documents, agreements and shared resources.</p></div><article class="dxcp-card"><?php dxcp_card_heading('SHARED WITH YOU','Project documents'); if (!$documents) : dxcp_empty('Ready for your first file','Documents shared by D’André will appear here. Task and support attachments stay with their conversations.','drive'); else : ?><div class="dxcp-document-grid"><?php foreach($documents as $document) : $url=dxcp_document_url($document->ID); ?><a class="dxcp-document" href="<?php echo esc_url($url); ?>"><span class="dxcp-document__icon"><?php echo dxcp_icon('drive'); ?></span><?php dxcp_badge(ucfirst(get_post_meta($document->ID,'_dxcp_document_type',true)?:'Document')); ?><h3><?php echo esc_html($document->post_title); ?></h3><p><?php echo esc_html(wp_trim_words(wp_strip_all_tags($document->post_content),15)); ?></p><small><?php echo get_post_meta($document->ID,'_dxcp_link_url',true)?'Open shared resource ↗':'Download private file ↓'; ?></small></a><?php endforeach; ?></div><?php endif; ?></article>
    <?php if (!$project) return; ?><article class="dxcp-card"><?php dxcp_card_heading('YOUR FOUNDATIONS','Client onboarding'); $onboarding=dxcp_onboarding_data($uid,$pid); if (!empty($onboarding['updated'])) : ?><p class="dxcp-muted">Last updated <?php echo esc_html(wp_date('j M Y',is_numeric($onboarding['updated'])?(int)$onboarding['updated']:strtotime($onboarding['updated']))); ?></p><?php endif; dxcp_form_start('dxcp_onboarding',$pid); ?><div class="dxcp-form-grid"><?php dxcp_field('Business or project name','business_name',$onboarding['business_name']??''); ?><label class="dxcp-field"><span>Content readiness</span><select name="content_ready"><?php foreach(['no'=>'Not started yet','in_progress'=>'In progress','yes'=>'Ready to share'] as $v=>$l) : ?><option value="<?php echo esc_attr($v); ?>" <?php selected($onboarding['content_ready']??'no',$v); ?>><?php echo esc_html($l); ?></option><?php endforeach; ?></select></label><label class="dxcp-field"><span>What would you like to achieve?</span><textarea name="project_goals" rows="4" maxlength="4000"><?php echo esc_textarea($onboarding['project_goals']??''); ?></textarea></label><label class="dxcp-field"><span>Who is your audience?</span><textarea name="audience" rows="4" maxlength="4000"><?php echo esc_textarea($onboarding['audience']??''); ?></textarea></label><label class="dxcp-field"><span>Preferred contact method</span><select name="preferred_contact"><option value="email" <?php selected($onboarding['preferred_contact']??'email','email'); ?>>Email</option><option value="phone" <?php selected($onboarding['preferred_contact']??'email','phone'); ?>>Phone</option></select></label></div><button class="dxcp-btn dxcp-btn--dark" type="submit">Save onboarding <?php echo dxcp_icon('check'); ?></button></form></article><?php }
function dxcp_render_payments($c) { extract($c); $pending_payments=array_values(array_filter($billing['payments'],fn($payment)=>$payment['status']==='pending')); ?><div class="dxcp-view-heading"><p class="dxcp-eyebrow">CLEAR FROM THE START</p><h1>Quotations & payments</h1><p>Your agreed balance, payment dates and project terms.</p></div><div class="dxcp-stats dxcp-stats--payments"><?php foreach(['Agreed project total'=>$billing['agreed_total_cents'],'Payments received'=>$billing['paid_cents'],'Balance remaining'=>$billing['balance_cents']] as $label=>$amount) : ?><article class="dxcp-stat"><span><small><?php echo esc_html($label); ?></small><strong class="dxcp-stat__money"><?php echo $amount===null?'To be agreed':esc_html(dxcp_money($amount)); ?></strong></span></article><?php endforeach; ?></div>
    <article class="dxcp-card"><?php dxcp_card_heading('THE AGREEMENT','Your quotations'); if (!$quotes) dxcp_empty('No quotation linked yet','Estimates generated while signed in are connected automatically. You can also securely connect an estimate made in this browser.','payments'); foreach($quotes as $q) : ?><div class="dxcp-quotation"><div class="dxcp-inline"><div><strong><?php echo esc_html($q['ref']); ?></strong><p><?php echo esc_html(dxcp_money($q['total_cents'])); ?> · <?php echo esc_html($q['kind']==='final'?'Final quotation':'Indicative estimate'); ?></p></div><?php dxcp_badge(ucwords(str_replace('_',' ',$q['status'])),$q['status']==='accepted'?'green':'gold'); ?><a class="dxcp-text-link" href="<?php echo esc_url($q['url']); ?>" target="_blank" rel="noopener noreferrer">Review document <?php echo dxcp_icon('external'); ?></a></div><p class="dxcp-muted"><?php echo esc_html($q['payment_terms']); ?></p><?php if (!empty($q['accepted_at'])) : ?><p class="dxcp-muted">Accepted <?php echo esc_html($q['accepted_at']); ?>. A new quotation version requires a new acceptance.</p><?php elseif (!empty($q['can_accept'])) : dxcp_form_start('dxcp_quote_action',$pid); ?><input type="hidden" name="quote_ref" value="<?php echo esc_attr($q['ref']); ?>"><input type="hidden" name="version" value="<?php echo esc_attr($q['version']); ?>"><input type="hidden" name="intent" value="accept_final"><label class="dxcp-checkbox"><input type="checkbox" name="confirmation" value="1" required><span>I have reviewed this final quotation, including its scope and payment terms, and I accept it.</span></label><button type="submit" class="dxcp-btn dxcp-btn--dark">Accept final quotation <?php echo dxcp_icon('check'); ?></button></form><?php elseif ($q['kind']==='indicative' && $q['status']!=='brief_confirmed' && (int)get_post_meta($pid,'_dxcp_client_id',true)===$uid) : dxcp_form_start('dxcp_quote_action',$pid); ?><input type="hidden" name="quote_ref" value="<?php echo esc_attr($q['ref']); ?>"><input type="hidden" name="version" value="<?php echo esc_attr($q['version']); ?>"><input type="hidden" name="intent" value="confirm_brief"><p>This estimate is a starting point. Confirming your brief asks D’André to review it; it does not accept a contract or make a payment.</p><button type="submit" class="dxcp-btn dxcp-btn--small">Confirm my brief <?php echo dxcp_icon('arrow'); ?></button></form><?php endif; ?></div><?php endforeach;
    if(true) : ?><details class="dxcp-disclosure"><summary>Connect an existing calculator estimate</summary><?php dxcp_form_start('dxcp_quote_claim',$pid); dxcp_field('Estimate reference','quote_ref',count(dxcp_claimable_estimates())===1?dxcp_claimable_estimates()[0]:'','text',true); dxcp_field('Private estimate key (if supplied)','estimate_token','','password'); ?><p class="dxcp-muted">An estimate made in this browser can be verified automatically. Otherwise, use its private key or ask D’André to link it for you.</p><button class="dxcp-btn dxcp-btn--small" type="submit">Connect estimate</button></form></details><?php endif; ?></article>
    <article class="dxcp-card"><?php dxcp_card_heading('YOUR PAYMENT PLAN','Dates & instalments'); if (!$billing['payments']) : dxcp_empty('No payments scheduled','Payment dates appear here after the final scope and payment plan are agreed. Your calculator estimate does not create a payment obligation.','payments'); else : ?><div class="dxcp-table-wrap"><table class="dxcp-table"><thead><tr><th>Payment</th><th>Amount</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($billing['payments'] as $payment) : ?><tr><td><strong><?php echo esc_html($payment['title']); ?></strong><?php if($payment['recurrence']) : ?><small><?php echo esc_html(ucfirst($payment['recurrence'])); ?></small><?php endif; ?></td><td><?php echo esc_html(dxcp_money($payment['amount_cents'])); ?></td><td><?php echo $payment['due_date']?esc_html(wp_date('j M Y',strtotime($payment['due_date']))):'Not scheduled'; ?></td><td><?php dxcp_badge(ucfirst($payment['status']),$payment['status']==='paid'?'green':''); ?></td><td><?php if($payment['payment_url'] && $payment['status']==='pending') : ?><a class="dxcp-text-link" href="<?php echo esc_url($payment['payment_url']); ?>" target="_blank" rel="noopener noreferrer">Payment link <?php echo dxcp_icon('external'); ?></a><?php else : ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php if($billing['agreement_url']) : ?><a class="dxcp-btn dxcp-btn--small" href="<?php echo esc_url($billing['agreement_url']); ?>">View payment agreement <?php echo dxcp_icon('external'); ?></a><?php endif; ?></article>
    <?php if ($pending_payments || $billing['deferrals']) : ?><article class="dxcp-card"><?php dxcp_card_heading('SOME ROOM TO BREATHE','Request a payment deferral'); ?><p>Let D’André know what would help. Your existing payment date and terms remain in place until a change is agreed.</p><?php if($pending_payments) : dxcp_form_start('dxcp_deferral',$pid); ?><div class="dxcp-form-grid"><label class="dxcp-field"><span>Which payment?</span><select name="payment_id" required><?php foreach($pending_payments as $payment) : ?><option value="<?php echo absint($payment['id']); ?>"><?php echo esc_html($payment['title'].' · '.dxcp_money($payment['amount_cents'])); ?></option><?php endforeach; ?></select></label><?php dxcp_field('Requested date','requested_date','','date',true); ?></div><label class="dxcp-field"><span>A little context</span><textarea name="reason" rows="3" maxlength="2000" required></textarea></label><button class="dxcp-btn dxcp-btn--small" type="submit">Send request</button></form><?php endif; foreach($billing['deferrals'] as $deferral) : ?><div class="dxcp-list-row"><span><strong>Requested <?php echo esc_html($deferral['requested_date']); ?></strong><small><?php echo esc_html($deferral['decision_note']?:'Awaiting review from D’André'); ?></small></span><?php dxcp_badge(ucfirst($deferral['status'])); ?></div><?php endforeach; ?></article><?php endif; }
function dxcp_render_sessions($c) { extract($c); ?><div class="dxcp-view-heading"><p class="dxcp-eyebrow">MAKE TIME FOR YOURSELF</p><h1>Your coaching calendar</h1><p>Upcoming sessions, locations and everything you need to be ready.</p></div><?php if($service!=='fitness') { dxcp_empty('Coaching has its own space','Your coaching sessions will appear here if a fitness coaching programme is assigned to your account.','sessions'); return; }
    $month=sanitize_text_field(wp_unslash($_GET['month']??wp_date('Y-m'))); if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$month)) $month=wp_date('Y-m'); $start=new DateTimeImmutable($month.'-01',wp_timezone()); $events=[]; foreach($sessions as $session) { $ts=dxcp_session_timestamp(get_post_meta($session->ID,'_dxcp_start',true)); if($ts) $events[wp_date('Y-m-d',$ts)][]=$session; }
    ?><article class="dxcp-card"><div class="dxcp-card__heading"><h2><?php echo esc_html($start->format('F Y')); ?></h2><div class="dxcp-inline"><a class="dxcp-btn dxcp-btn--small" aria-label="Previous month" href="<?php echo esc_url(dxcp_portal_url('sessions',$pid,['month'=>$start->modify('-1 month')->format('Y-m')])); ?>">←</a><a class="dxcp-btn dxcp-btn--small" aria-label="Next month" href="<?php echo esc_url(dxcp_portal_url('sessions',$pid,['month'=>$start->modify('+1 month')->format('Y-m')])); ?>">→</a></div></div><p class="dxcp-muted">All session times are shown in <?php echo esc_html(wp_timezone_string()?:'Europe/London'); ?>.</p><div class="dxcp-calendar"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day) echo '<span class="dxcp-calendar__day">'.esc_html($day).'</span>'; for($n=1;$n<(int)$start->format('N');$n++) echo '<span class="dxcp-calendar__blank"></span>'; for($day=1;$day<=(int)$start->format('t');$day++) : $key=$start->format('Y-m-').sprintf('%02d',$day); ?><div class="dxcp-calendar__cell <?php echo $key===wp_date('Y-m-d')?'is-today':''; ?>"><span><?php echo $day; ?></span><?php foreach($events[$key]??[] as $session) : $ts=dxcp_session_timestamp(get_post_meta($session->ID,'_dxcp_start',true)); ?><a href="#dxcp-session-<?php echo absint($session->ID); ?>"><?php echo esc_html(wp_date('H:i',$ts).' '.$session->post_title); ?></a><?php endforeach; ?></div><?php endfor; ?></div></article>
    <article class="dxcp-card"><?php dxcp_card_heading('SHOW UP FOR YOURSELF','Session details'); if(!$sessions) dxcp_empty('Your calendar is clear','Your coach will add your agreed sessions here. Start a support conversation to arrange your next session.','sessions'); foreach($sessions as $session) : $ts=dxcp_session_timestamp(get_post_meta($session->ID,'_dxcp_start',true)); $join=get_post_meta($session->ID,'_dxcp_join_url',true); ?><div class="dxcp-session" id="dxcp-session-<?php echo absint($session->ID); ?>"><div class="dxcp-session__date"><strong><?php echo $ts?esc_html(wp_date('d',$ts)):'—'; ?></strong><span><?php echo $ts?esc_html(wp_date('M',$ts)):''; ?></span></div><div><h3><?php echo esc_html($session->post_title); ?></h3><p><?php echo $ts?esc_html(wp_date('l j F · H:i',$ts)): 'Time to be confirmed'; ?> · <?php echo esc_html(get_post_meta($session->ID,'_dxcp_location',true)?:'Location to be confirmed'); ?></p><p><?php echo esc_html(wp_strip_all_tags($session->post_content)); ?></p></div><?php dxcp_badge(ucfirst(get_post_meta($session->ID,'_dxcp_status',true)?:'scheduled')); if($join && get_post_meta($session->ID,'_dxcp_status',true)!=='cancelled') : ?><a class="dxcp-btn dxcp-btn--small" href="<?php echo esc_url($join); ?>" target="_blank" rel="noopener noreferrer">Join session <?php echo dxcp_icon('external'); ?></a><?php endif; ?></div><?php endforeach; ?></article><?php }
function dxcp_render_profile($c) { extract($c); $profile=dxcp_profile_data($uid); ?><div class="dxcp-view-heading"><p class="dxcp-eyebrow">A FEW ESSENTIALS</p><h1>Your details</h1><p>Keep your contact information up to date.</p></div><article class="dxcp-card"><?php dxcp_card_heading('YOUR ACCOUNT','Client details'); dxcp_form_start('dxcp_profile',$pid); ?><div class="dxcp-form-grid"><?php dxcp_field('Display name','display_name',$profile['display_name']??$user->display_name,'text',true); dxcp_field('Company','company',$profile['company']??''); dxcp_field('Phone number','phone',$profile['phone']??'','tel'); dxcp_field('Website','website',$profile['website']??'','url'); ?></div><div class="dxcp-callout"><strong>Account email</strong><p><?php echo esc_html($user->user_email); ?></p><small>For changes to your email, billing identity or account access, contact D’André so we can verify the details together.</small></div><button type="submit" class="dxcp-btn dxcp-btn--dark">Save details <?php echo dxcp_icon('check'); ?></button></form></article><?php }
function dxcp_render_activity($c) { extract($c); $activity=[]; foreach(array_merge($tasks,$tickets,$documents,$sessions) as $record) $activity[]=['title'=>$record->post_title,'date'=>dxcp_updated_timestamp($record),'url'=>in_array($record->post_type,['ticket','dxcp_task'],true)?dxcp_record_url($record->ID):dxcp_portal_url($record->post_type==='dxcp_session'?'sessions':'drive',$pid),'type'=>['ticket'=>'Support','dxcp_task'=>'To-do','dxcp_document'=>'Drive','dxcp_session'=>'Coaching'][$record->post_type]??'Project']; usort($activity,fn($a,$b)=>$b['date']<=>$a['date']); ?>
    <aside class="dxcp-rail"><article class="dxcp-partner"><div class="dxcp-partner__portrait"><img src="<?php echo esc_url(get_template_directory_uri().'/assets/img/headshot.webp'); ?>" alt="D’André Phillips" loading="lazy"></div><p class="dxcp-eyebrow">YOUR PROJECT PARTNER</p><h2>D’André Phillips<span>✦</span></h2><p>A little clarity.<br>Some forward momentum.</p><a class="dxcp-btn dxcp-btn--dark" href="<?php echo esc_url(dxcp_portal_url('support',$pid,['new_ticket'=>1])); ?>">Let’s talk <?php echo dxcp_icon('arrow'); ?></a></article><article class="dxcp-card dxcp-activity"><p class="dxcp-eyebrow">KEEPING YOU IN THE LOOP</p><h2>Recent activity</h2><?php if(!$activity) : ?><p class="dxcp-muted">Your project updates will appear here.</p><?php endif; foreach(array_slice($activity,0,5) as $event) : ?><a href="<?php echo esc_url($event['url']); ?>"><span class="dxcp-activity__dot"></span><span><small><?php echo esc_html($event['type']); ?> updated</small><strong><?php echo esc_html($event['title']); ?></strong><time><?php echo esc_html(human_time_diff((int)$event['date'],time())); ?> ago</time></span></a><?php endforeach; ?></article><div class="dxcp-privacy-note"><?php echo dxcp_icon('check'); ?><span>A private space for you and your project team.</span></div></aside>
<?php }

function dxcp_render_attachment_preview($file) {
    if (empty($file['url']) || empty($file['mime'])) return;
    $url = add_query_arg('inline','1',$file['url']);
    if (strpos($file['mime'],'image/')===0) echo '<a class="dxcp-media-preview" href="'.esc_url($url).'" target="_blank" rel="noopener"><img src="'.esc_url($url).'" alt="'.esc_attr($file['title']).'" loading="lazy"></a>';
    elseif (strpos($file['mime'],'video/')===0) echo '<video class="dxcp-media-preview" controls preload="metadata" src="'.esc_url($url).'"></video>';
    elseif (strpos($file['mime'],'audio/')===0) echo '<audio class="dxcp-media-preview" controls preload="metadata" src="'.esc_url($url).'"></audio>';
}

function dxcp_task_display_status($id) {
    return get_post_meta($id,'_dxcp_completion_requested',true) ? 'Ready for review' : dxcp_task_status_label(get_post_meta($id,'_dxcp_task_status',true)?:'todo');
}
function dxcp_updated_timestamp($record) {
    $stamp = (int)get_post_modified_time('U',true,$record);
    foreach (['_dxcp_last_updated','ticket_last_updated'] as $key) {
        $value = get_post_meta($record->ID,$key,true);
        if ($value) { try { $stamp=max($stamp,(new DateTimeImmutable($value,wp_timezone()))->getTimestamp()); } catch(Exception $e) {} }
    }
    return $stamp;
}
